import { test, expect, Page } from '@playwright/test';

test.describe('Browser Back Button Navigation', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('https://example.com');
  });

  test('should maintain app state when using browser back button from product page', async () => {
    // Navigate to products page
    await page.getByRole('link', { name: /products/i }).click();
    await page.waitForURL('**/products');

    // Verify products page loaded
    const productsHeading = page.getByRole('heading', { name: /products/i });
    await expect(productsHeading).toBeVisible();

    // Click on a specific product
    await page.getByRole('link', { name: /product 1/i }).click();
    await page.waitForURL('**/products/1');

    // Verify product details page loaded
    const productTitle = page.getByRole('heading', { name: /product 1/i });
    await expect(productTitle).toBeVisible();

    // Store product page URL
    const productPageUrl = page.url();

    // Use browser back button
    await page.goBack();
    await page.waitForURL('**/products');

    // Verify we're back on products page
    await expect(productsHeading).toBeVisible();

    // Verify products list is still rendered
    const productLinks = page.getByRole('link', { name: /product \d/i });
    await expect(productLinks).toHaveCount(5);

    // Navigate forward to verify state consistency
    await page.goForward();
    await page.waitForURL(productPageUrl);

    // Verify product details are still intact
    await expect(productTitle).toBeVisible();
  });

  test('should preserve form state when navigating back from checkout', async () => {
    // Navigate to cart
    await page.getByRole('link', { name: /cart/i }).click();
    await page.waitForURL('**/cart');

    // Verify cart page loaded
    const cartHeading = page.getByRole('heading', { name: /shopping cart/i });
    await expect(cartHeading).toBeVisible();

    // Proceed to checkout
    await page.getByRole('button', { name: /proceed to checkout/i }).click();
    await page.waitForURL('**/checkout');

    // Fill in checkout form
    await page.getByLabel(/email/i).fill('test@example.com');
    await page.getByLabel(/full name/i).fill('John Doe');
    await page.getByLabel(/address/i).fill('123 Main St');

    // Store form values
    const emailValue = await page.getByLabel(/email/i).inputValue();
    const nameValue = await page.getByLabel(/full name/i).inputValue();
    const addressValue = await page.getByLabel(/address/i).inputValue();

    // Navigate back using browser back button
    await page.goBack();
    await page.waitForURL('**/cart');

    // Verify we're back on cart page
    await expect(cartHeading).toBeVisible();

    // Navigate forward to checkout
    await page.goForward();
    await page.waitForURL('**/checkout');

    // Verify form state is preserved
    await expect(page.getByLabel(/email/i)).toHaveValue(emailValue);
    await expect(page.getByLabel(/full name/i)).toHaveValue(nameValue);
    await expect(page.getByLabel(/address/i)).toHaveValue(addressValue);
  });

  test('should handle multiple back navigations without breaking app state', async () => {
    // Navigate through multiple pages
    await page.getByRole('link', { name: /products/i }).click();
    await page.waitForURL('**/products');

    await page.getByRole('link', { name: /product 2/i }).click();
    await page.waitForURL('**/products/2');

    await page.getByRole('button', { name: /add to cart/i }).click();

    // Verify item added
    const cartBadge = page.getByText(/cart.*1/i);
    await expect(cartBadge).toBeVisible();

    // Navigate to cart
    await page.getByRole('link', { name: /cart/i }).click();
    await page.waitForURL('**/cart');

    // Verify cart contains item
    const cartItems = page.getByRole('row', { name: /product 2/i });
    await expect(cartItems).toBeVisible();

    // Go back to product page
    await page.goBack();
    await page.waitForURL('**/products/2');

    // Verify product page state
    const productTitle = page.getByRole('heading', { name: /product 2/i });
    await expect(productTitle).toBeVisible();

    // Go back to products list
    await page.goBack();
    await page.waitForURL('**/products');

    // Verify products list is intact
    const productsHeading = page.getByRole('heading', { name: /products/i });
    await expect(productsHeading).toBeVisible();

    // Go back to home
    await page.goBack();
    await page.waitForURL('**/');

    // Verify home page loaded
    const homeHeading = page.getByRole('heading', { name: /welcome/i });
    await expect(homeHeading).toBeVisible();
  });

  test('should maintain scroll position when navigating back', async () => {
    // Navigate to products page
    await page.getByRole('link', { name: /products/i }).click();
    await page.waitForURL('**/products');

    // Scroll down to load more products
    await page.evaluate(() => window.scrollBy(0, 500));

    // Get scroll position
    const scrollPositionBefore = await page.evaluate(() => window.scrollY);

    // Click on a product
    await page.getByRole('link', { name: /product 5/i }).click();
    await page.waitForURL('**/products/5');

    // Navigate back
    await page.goBack();
    await page.waitForURL('**/products');

    // Verify scroll position is restored
    const scrollPositionAfter = await page.evaluate(() => window.scrollY);
    expect(scrollPositionAfter).toBe(scrollPositionBefore);
  });

  test('should handle back navigation with dynamic content loading', async () => {
    // Navigate to products page
    await page.getByRole('link', { name: /products/i }).click();
    await page.waitForURL('**/products');

