    await page.waitForSelector('[data-testid="product-item"]');

    // Count filtered products
    const filteredProducts = page.getByTestId('product-item');
    const filteredCount = await filteredProducts.count();

    // Navigate to a product
    await page.getByRole('link', { name: /product 1/i }).click();
    await page.waitForURL('**/products/1');

    // Go back
    await page.goBack();
    await page.waitForURL('**/products');

    // Verify filter is still applied
    const filterButton = page.getByRole('button', { name: /filter/i });
    await expect(filterButton).toBeVisible();

